"""Regenerate the browser vocabulary from the shared, reviewed Python strings."""

import json
from pathlib import Path

from app.ui_i18n import MESSAGES


def main():
    path = Path(__file__).resolve().parents[1] / "app/static/i18n.js"
    path.write_text(
        "// Generated by python -m scripts.build_ui_translations; edit app/ui_i18n.py.\nexport const messages = "
        + json.dumps(MESSAGES, ensure_ascii=False, separators=(",", ":"))
        + ";\n"
    )


if __name__ == "__main__":
    main()
